<?php
define('CSRFCHECK_WITH_TOKEN', 1);
require $_SERVER['DOCUMENT_ROOT'].'/main.inc.php';
require_once __DIR__.'/../lib/main.lib.php';
require_once __DIR__.'/../class/OperationsSopService.class.php';
require_once DOL_DOCUMENT_ROOT.'/custom/chinaplanetcustomercenter/lib/admin_shell.lib.php';
cpo_require($user, 'read');
$langs->load('chinaplanetoperations@chinaplanetoperations');
$contentLang = cpo_content_language();
$service = new OperationsSopService($db);
$id = GETPOSTINT('id'); $action=GETPOST('action','aZ09');
$canWrite=cpo_can($user,'write'); $canPublish=cpo_can($user,'publish'); $canDelete=cpo_can($user,'delete');
try {
    if($action==='publish'){cpo_require($user,'publish');$service->publish($id,(int)$user->id);setEventMessages($langs->trans('Published'),null,'mesgs');}
    elseif($action==='archive'){cpo_require($user,'publish');$service->archive($id,(int)$user->id);setEventMessages($langs->trans('Archived'),null,'mesgs');}
    elseif($action==='restore'){cpo_require($user,'publish');$service->restore($id,(int)$user->id);setEventMessages($langs->trans('Restore'),null,'mesgs');}
    elseif($action==='restore_revision'){cpo_require($user,'publish');$service->restoreRevision($id,GETPOSTINT('revision'),(int)$user->id);setEventMessages($langs->trans('RestoreRevision'),null,'mesgs');}
    elseif($action==='delete'){cpo_require($user,'delete');$service->delete($id,(int)$user->id);setEventMessages($langs->trans('Deleted'),null,'mesgs');header('Location:index.php?content_lang='.urlencode($contentLang));exit;}
} catch(Throwable $e){setEventMessages($e->getMessage(),null,'errors');}
$sop=$service->get($id,$contentLang,$canWrite||$canPublish||$canDelete);if(!$sop)accessforbidden();
$translations=$sop['translations'];$completeness=$service->translationCompleteness($translations);$revisions=$service->getRevisions($id);
$statusLabels=array(-1=>'Deleted',0=>'Draft',1=>'Active',9=>'Archived');$revisionLabels=array(0=>'Draft',1=>'Published',9=>'Superseded');
$morecss=array(cpo_asset('/custom/chinaplanetoperations/css/operations.css'),cpcc_admin_shell_asset('/custom/chinaplanetcustomercenter/css/admin_dashboard.css'));llxHeader('',dol_escape_htmltag($sop['title']),'','',0,0,array(),$morecss);cpcc_admin_shell_open('sop',$sop['title'],$sop['category_label']?:$langs->trans('Uncategorized'),'fa-book-open');
$postButton=function($action,$label,$class='button',$confirm='')use($id,$contentLang){ ?><form method="post" class="cpo-inline-form"<?php echo $confirm?' onsubmit="return confirm(\''.dol_escape_js($confirm).'\')"':''; ?>><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="id" value="<?php echo (int)$id; ?>"><input type="hidden" name="content_lang" value="<?php echo dol_escape_htmltag($contentLang); ?>"><input type="hidden" name="action" value="<?php echo $action; ?>"><button class="<?php echo $class; ?>"><?php echo dol_escape_htmltag($label); ?></button></form><?php };
?>
<main class="cpo-page"><section class="cpo-hero"><div><span class="cpo-eyebrow"><?php echo dol_escape_htmltag($sop['ref']); ?> · <?php echo $langs->trans('Revision').' '.(int)$sop['revision_no']; ?></span><h1><?php echo dol_escape_htmltag($sop['title']); ?></h1><p><?php echo dol_escape_htmltag($sop['category_label']?:$langs->trans('Uncategorized')); ?></p></div><div><?php echo cpo_language_switcher($contentLang,array('id'=>$id)); ?><div class="cpo-actions" style="margin-top:8px"><a class="button" href="index.php?content_lang=<?php echo urlencode($contentLang); ?>"><?php echo $langs->trans('BackToLibrary'); ?></a><a class="button" target="_blank" href="print.php?id=<?php echo (int)$id; ?>&content_lang=<?php echo urlencode($contentLang); ?>"><?php echo $langs->trans('Print'); ?></a><?php if($canWrite){ ?><a class="button" href="edit.php?id=<?php echo (int)$id; ?>&content_lang=<?php echo urlencode($contentLang); ?>"><?php echo $langs->trans('EditNewRevision'); ?></a><?php } ?></div></div></section>
<section class="cpo-panel"><div class="cpo-panel-head"><h2><?php echo $langs->trans('TranslationCoverage'); ?></h2><div class="cpo-actions"><?php if($canPublish&&(int)$sop['revision_status']===0)$postButton('publish',$langs->trans('PublishTranslations'),'button button-save','Approve all required translations and publish this revision?');if($canPublish&&(int)$sop['status']===1)$postButton('archive',$langs->trans('Archive'),'button','Archive this SOP?');if($canPublish&&(int)$sop['status']===9)$postButton('restore',$langs->trans('Restore'),'button button-save');if($canDelete)$postButton('delete',$langs->trans('Delete'),'button button-delete','Delete this SOP from the working library?'); ?></div></div><div class="cpo-translation-badges"><?php foreach(OperationsSopService::supportedLanguages() as $code=>$meta){$ready=!empty($completeness[$code]);$approved=!empty($translations[$code])&&(int)$translations[$code]['translation_status']===2;?><span class="cpo-badge <?php echo $approved?'cpo-lang-ready':($ready?'cpo-lang-review':'cpo-lang-missing'); ?>"><?php echo $meta['short'].' · '.$langs->trans($approved?'TranslationReady':($ready?'TranslationReview':'TranslationMissing')); ?></span><?php } ?></div></section>
<article class="cpo-panel cpo-detail" dir="<?php echo OperationsSopService::supportedLanguages()[$contentLang]['dir']; ?>"><header><div><div class="cpo-card-meta"><span class="cpo-badge"><?php echo dol_escape_htmltag($sop['ref']); ?></span><span class="cpo-badge status-<?php echo (int)$sop['status']; ?>"><?php echo $langs->trans($statusLabels[(int)$sop['status']]??'Status'); ?></span></div><h1><?php echo dol_escape_htmltag($sop['title']); ?></h1><p><?php echo nl2br(dol_escape_htmltag($sop['applicability']?:$langs->trans('GeneralProcedure'))); ?></p></div><dl><dt><?php echo $langs->trans('Revision'); ?></dt><dd><?php echo (int)$sop['revision_no']; ?></dd><dt><?php echo $langs->trans('EffectiveDate'); ?></dt><dd><?php echo dol_escape_htmltag($sop['effective_date']?:'—'); ?></dd><dt><?php echo $langs->trans('Department'); ?></dt><dd><?php echo dol_escape_htmltag($sop['responsible_department']?:'—'); ?></dd><dt><?php echo $langs->trans('UpdatedBy'); ?></dt><dd><?php echo dol_escape_htmltag($sop['updated_by']?:'—'); ?></dd></dl></header>
<section><h2><?php echo $langs->trans('Scope'); ?></h2><div class="cpo-scope"><?php foreach(array('Country'=>$sop['country_code'],'POL'=>$sop['pol'],'POD'=>$sop['pod'],'ShippingLine'=>$sop['shipping_line'],'ServiceType'=>$sop['service_type'],'ContainerType'=>$sop['container_type'],'Incoterm'=>$sop['incoterm'],'CargoType'=>$sop['cargo_type']) as $label=>$value){ ?><div><span><?php echo $langs->trans($label); ?></span><strong><?php echo dol_escape_htmltag($value?:$langs->trans('All')); ?></strong></div><?php } ?></div></section>
<?php $renderList=function($label,$value,$ordered=false,$class='')use($langs){$items=OperationsSopService::decodeList($value);if(!$items)return;?><section class="<?php echo $class; ?>"><h2><?php echo $langs->trans($label); ?></h2><<?php echo $ordered?'ol':'ul'; ?>><?php foreach($items as $item){ ?><li><?php echo nl2br(dol_escape_htmltag($item)); ?></li><?php } ?></<?php echo $ordered?'ol':'ul'; ?>></section><?php };$renderList('RequiredInformation',$sop['required_information']);$renderList('ProcedureSteps',$sop['procedure_steps'],true);$renderList('RequiredDocuments',$sop['required_documents']);$renderList('ImportantWarnings',$sop['warnings'],false,'cpo-warnings');if($sop['escalation_instructions']){ ?><section class="cpo-escalation"><h2><?php echo $langs->trans('EscalationInstructions'); ?></h2><p><?php echo nl2br(dol_escape_htmltag($sop['escalation_instructions'])); ?></p></section><?php }if($sop['internal_notes']){ ?><section><h2><?php echo $langs->trans('InternalNotes'); ?></h2><p><?php echo nl2br(dol_escape_htmltag($sop['internal_notes'])); ?></p></section><?php } ?>
</article>
<section class="cpo-panel"><div class="cpo-panel-head"><h2><?php echo $langs->trans('RevisionHistory'); ?></h2></div><div class="div-table-responsive"><table class="cpo-table"><thead><tr><th><?php echo $langs->trans('Revision'); ?></th><th><?php echo $langs->trans('Status'); ?></th><th><?php echo $langs->trans('TranslationCoverage'); ?></th><th><?php echo $langs->trans('UpdatedBy'); ?></th><th><?php echo $langs->trans('EffectiveDate'); ?></th><th></th></tr></thead><tbody><?php foreach($revisions as $revision){ ?><tr><td><?php echo (int)$revision['revision_no']; ?></td><td><?php echo $langs->trans($revisionLabels[(int)$revision['revision_status']]??'Status'); ?></td><td><?php echo (int)$revision['approved_languages']; ?>/3</td><td><?php echo dol_escape_htmltag($revision['user_login']?:'—'); ?></td><td><?php echo dol_escape_htmltag($revision['effective_date']?:'—'); ?></td><td><a class="button smallpaddingimp" target="_blank" href="print.php?id=<?php echo (int)$id; ?>&revision=<?php echo (int)$revision['revision_no']; ?>&content_lang=<?php echo urlencode($contentLang); ?>"><?php echo $langs->trans('Open'); ?></a><?php if($canPublish&&(int)$revision['revision_no']!==(int)$sop['revision_no']){ ?><form method="post" class="cpo-inline-form" onsubmit="return confirm('Restore this revision as a new published revision?')"><input type="hidden" name="token" value="<?php echo newToken(); ?>"><input type="hidden" name="action" value="restore_revision"><input type="hidden" name="id" value="<?php echo (int)$id; ?>"><input type="hidden" name="revision" value="<?php echo (int)$revision['revision_no']; ?>"><input type="hidden" name="content_lang" value="<?php echo dol_escape_htmltag($contentLang); ?>"><button class="button smallpaddingimp"><?php echo $langs->trans('RestoreRevision'); ?></button></form><?php } ?></td></tr><?php } ?></tbody></table></div></section></main>
<?php cpcc_admin_shell_close();llxFooter();$db->close(); ?>
